from itertools import product
N = 3                                              # every object may be a book and/or a member
def unborrowed(b, bk, mm, br):                     # no member has borrowed object b
    return not any(mm[m] and br[m][b] for m in range(N))
target = lambda bk, mm, br: any(bk[b] and unborrowed(b, bk, mm, br) for b in range(N))
opts = {
 "A": lambda bk, mm, br: any((not bk[b]) or unborrowed(b, bk, mm, br) for b in range(N)),
 "B": lambda bk, mm, br: not any(bk[b] and mm[m] and br[m][b] for b in range(N) for m in range(N)),
 "C": lambda bk, mm, br: any(bk[b] and all((not mm[m]) or (not br[m][b]) for m in range(N)) for b in range(N)),
 "D": lambda bk, mm, br: all((not mm[m]) or any(bk[b] and not br[m][b] for b in range(N)) for m in range(N)),
}
diff = dict.fromkeys(opts, 0)
for bk in product([0, 1], repeat=N):
    for mm in product([0, 1], repeat=N):
        for flat in product([0, 1], repeat=N * N):
            br = [flat[i * N:(i + 1) * N] for i in range(N)]
            t = target(bk, mm, br)
            for k, f in opts.items():
                diff[k] += f(bk, mm, br) != t
print(diff)                                        # only C has zero disagreements
assert [k for k, v in diff.items() if v == 0] == ["C"]

